{"cmd":"cat <<'EOF' > /root/environment/skills/js-number-formatting.md
# JavaScript Number Formatting (Market Cap)

## Purpose
Format large numeric values into human-readable abbreviations (K/M/B/T).

## Pattern
```js
const formatCap = value => {
  const n = +value;
  if (!isFinite(n)) return "—";
  const abs = Math.abs(n);
  if (abs >= 1e12) return (n / 1e12).toFixed(2).replace(/\.0+$/, "") + "T";
  if (abs >= 1e9) return (n / 1e9).toFixed(2).replace(/\.0+$/, "") + "B";
  if (abs >= 1e6) return (n / 1e6).toFixed(2).replace(/\.0+$/, "") + "M";
  if (abs >= 1e3) return (n / 1e3).toFixed(2).replace(/\.0+$/, "") + "K";
  return n.toString();
};
```

## Notes
- Use this for table display and tooltip values.
- Return a dash for missing values (ETFs).
```
EOF"}

{"cmd":"cat <<'EOF' > /root/output/js/visualization.js
/* global d3 */
(() => {
  const bubbleSvg = d3.select("#bubble-svg");
  const bubbleContainer = d3.select("#bubble-container").node();
  const tooltip = d3.select("#tooltip");
  const legend = d3.select("#legend");
  const tableRoot = d3.select("#stock-table");
  const historySvg = d3.select("#history-svg");
  const historyTitle = d3.select("#history-title");
  const historyEmpty = d3.select("#history-empty");

  const chartHeight = 520;
  const historyHeight = 240;
  const historyMargin = { top: 28, right: 26, bottom: 32, left: 48 };

  const formatCap = (value) => {
    const n = +value;
    if (!isFinite(n)) return "—";
    const abs = Math.abs(n);
    if (abs >= 1e12) return (n / 1e12).toFixed(2).replace(/\.0+$/, "") + "T";
    if (abs >= 1e9) return (n / 1e9).toFixed(2).replace(/\.0+$/, "") + "B";
    if (abs >= 1e6) return (n / 1e6).toFixed(2).replace(/\.0+$/, "") + "M";
    if (abs >= 1e3) return (n / 1e3).toFixed(2).replace(/\.0+$/, "") + "K";
    return n.toString();
  };

  const palette = [
    "#3C6E71",
    "#E07A5F",
    "#8D5A97",
    "#2A9D8F",
    "#F2CC8F",
    "#4A4E69",
    "#1F7A8C",
    "#C97C5D",
    "#6B8E23",
    "#B84A62",
    "#56638A",
    "#D9A441",
    "#5E6472",
    "#9A8C98"
  ];

  const historyCache = new Map();

  const loadHistory = (ticker) => {
    if (historyCache.has(ticker)) return Promise.resolve(historyCache.get(ticker));
    const urls = [
      `data/indiv-stock/${ticker}.csv`,
      `data/indiv-stock/${ticker.toLowerCase()}.csv`
    ];

    const row = (d) => ({
      date: new Date(d.Date),
      close: +d.Close
    });

    return d3.csv(urls[0], row)
      .catch(() => d3.csv(urls[1], row))
      .then((data) => {
        historyCache.set(ticker, data);
        return data;
      })
      .catch(() => []);
  };

  const renderHistory = (data, ticker) => {
    const width = bubbleContainer.clientWidth + d3.select("#table-panel").node().clientWidth + 24;
    const viewWidth = Math.max(width, 640);
    historySvg
      .attr("viewBox", [0, 0, viewWidth, historyHeight])
      .attr("preserveAspectRatio", "xMidYMid meet");

    historySvg.selectAll("*").remove();

    if (!data || data.length === 0) {
      historyEmpty.classed("hidden", false);
      historyTitle.text("Select a company to view price history");
      return;
    }

    historyEmpty.classed("hidden", true);
    historyTitle.text(`${ticker} price history (Close)`);

    const x = d3.scaleTime()
      .domain(d3.extent(data, (d) => d.date))
      .range([historyMargin.left, viewWidth - historyMargin.right]);

    const y = d3.scaleLinear()
      .domain(d3.extent(data, (d) => d.close))
      .nice()
      .range([historyHeight - historyMargin.bottom, historyMargin.top]);

    const line = d3.line()
      .x((d) => x(d.date))
      .y((d) => y(d.close));

    historySvg.append("path")
      .datum(data)
      .attr("class", "history-line")
      .attr("d", line);

    historySvg.append("g")
      .attr("transform", `translate(0, ${historyHeight - historyMargin.bottom})`)
      .call(d3.axisBottom(x).ticks(6));

    historySvg.append("g")
      .attr("transform", `translate(${historyMargin.left}, 0)`)
      .call(d3.axisLeft(y).ticks(5));
  };

  const init = async () => {
    const data = await d3.csv("data/stock-descriptions.csv", (d) => {
      const cap = d.marketCap && d.marketCap.trim() !== "" ? +d.marketCap : null;
      return {
        ticker: d.ticker,
        sector: d.sector,
        name: d["full name"],
        marketCap: cap,
        isETF: cap === null || Number.isNaN(cap)
      };
    });

    const sectors = Array.from(new Set(data.map((d) => d.sector))).sort();
    const color = d3.scaleOrdinal()
      .domain(sectors)
      .range(palette.concat(palette));

    const capExtent = d3.extent(data.filter((d) => d.marketCap !== null), (d) => d.marketCap);
    const sizeScale = d3.scaleSqrt()
      .domain(capExtent)
      .range([12, 48]);

    data.forEach((d) => {
      d.radius = d.isETF ? 16 : sizeScale(d.marketCap);
    });

    const width = bubbleContainer.clientWidth;
    bubbleSvg
      .attr("viewBox", [0, 0, width, chartHeight])
      .attr("preserveAspectRatio", "xMidYMid meet");

    const centers = new Map();
    const computeCenters = () => {
      const radius = Math.min(width, chartHeight) * 0.22;
      sectors.forEach((sector, i) => {
        const angle = (i / sectors.length) * Math.PI * 2;
        centers.set(sector, {
          x: width / 2 + Math.cos(angle) * radius,
          y: chartHeight / 2 + Math.sin(angle) * radius * 0.8
        });
      });
    };
    computeCenters();

    const simulation = d3.forceSimulation(data)
      .force("x", d3.forceX((d) => centers.get(d.sector).x).strength(0.08))
      .force("y", d3.forceY((d) => centers.get(d.sector).y).strength(0.08))
      .force("collide", d3.forceCollide((d) => d.radius + 1).iterations(2))
      .force("charge", d3.forceManyBody().strength(0.5))
      .force("center", d3.forceCenter(width / 2, chartHeight / 2))
      .alphaDecay(0.02);

    const node = bubbleSvg.selectAll("g.node")
      .data(data, (d) => d.ticker)
      .join((enter) => {
        const g = enter.append("g").attr("class", "node");
        g.append("circle")
          .attr("r", (d) => d.radius)
          .attr("fill", (d) => color(d.sector));

        g.append("text")
          .text((d) => d.ticker)
          .attr("class", "node-label")
          .attr("text-anchor", "middle")
          .attr("dy", "0.3em")
          .style("font-size", (d) => `${Math.min(14, Math.max(9, d.radius / 1.6))}px`);

        return g;
      });

    simulation.on("tick", () => {
      node.attr("transform", (d) => `translate(${d.x}, ${d.y})`);
    });

    const selectKey = (ticker) => {
      node.classed("selected", (d) => d.ticker === ticker);
      d3.selectAll("tbody tr").classed("selected", (d) => d.ticker === ticker);
      loadHistory(ticker).then((history) => renderHistory(history, ticker));
    };

    node
      .on("mouseenter", (event, d) => {
        if (d.isETF) return;
        tooltip
          .classed("hidden", false)
          .html(`
            <div class="tooltip-title">${d.ticker}</div>
            <div class="tooltip-name">${d.name}</div>
            <div class="tooltip-sector">Sector: ${d.sector}</div>
          `);
      })
      .on("mousemove", (event, d) => {
        if (d.isETF) return;
        tooltip
          .style("left", `${event.pageX + 14}px`)
          .style("top", `${event.pageY - 28}px`);
      })
      .on("mouseleave", () => {
        tooltip.classed("hidden", true);
      })
      .on("click", (event, d) => {
        event.stopPropagation();
        selectKey(d.ticker);
      });

    bubbleSvg.on("click", () => {
      node.classed("selected", false);
      d3.selectAll("tbody tr").classed("selected", false);
      historySvg.selectAll("*").remove();
      historyEmpty.classed("hidden", false);
      historyTitle.text("Select a company to view price history");
    });

    legend
      .selectAll("div")
      .data(sectors)
      .join("div")
      .attr("class", "legend-item")
      .html((d) => `
        <span class="legend-swatch" style="background:${color(d)}"></span>
        <span>${d}</span>
      `);

    const columns = [
      { label: "Ticker symbol", key: "ticker" },
      { label: "Full company name", key: "name" },
      { label: "Sector", key: "sector" },
      { label: "Market cap", key: "marketCap" }
    ];

    const thead = tableRoot.append("thead").append("tr");
    thead.selectAll("th")
      .data(columns)
      .enter()
      .append("th")
      .text((d) => d.label);

    const tbody = tableRoot.append("tbody");

    const rows = tbody.selectAll("tr")
      .data(data, (d) => d.ticker)
      .enter()
      .append("tr")
      .attr("data-key", (d) => d.ticker)
      .classed("is-etf", (d) => d.isETF)
      .on("click", (event, d) => {
        selectKey(d.ticker);
      });

    rows.selectAll("td")
      .data((d) => [
        d.ticker,
        d.name,
        d.sector,
        formatCap(d.marketCap)
      ])
      .enter()
      .append("td")
      .text((d) => d);

    window.addEventListener("resize", () => {
      const newWidth = bubbleContainer.clientWidth;
      bubbleSvg.attr("viewBox", [0, 0, newWidth, chartHeight]);
      simulation.force("center", d3.forceCenter(newWidth / 2, chartHeight / 2));
      const radius = Math.min(newWidth, chartHeight) * 0.22;
      sectors.forEach((sector, i) => {
        const angle = (i / sectors.length) * Math.PI * 2;
        centers.set(sector, {
          x: newWidth / 2 + Math.cos(angle) * radius,
          y: chartHeight / 2 + Math.sin(angle) * radius * 0.8
        });
      });
      simulation
        .force("x", d3.forceX((d) => centers.get(d.sector).x).strength(0.08))
        .force("y", d3.forceY((d) => centers.get(d.sector).y).strength(0.08))
        .alpha(0.6)
        .restart();
    });
  };

  init();
})();
EOF"}

